/**
 * 塔罗大师解读 · 事业工作 · 具体问题 × 78 张牌 × 正逆位
 *
 * 【产品标准】大师级：每一条须独立成篇，贴「本题措辞 + 该牌画面与正逆」，禁止套话批发。
 * 【重复控制】全库写作时轮换意象与句式，避免同一比喻（悬崖、蒙眼布、盾牌等）在多篇堆叠；
 *   同一问题下 156 条之间也要错开切入角度，不重复使用相同起句与排比骨架。
 * 【结构】五段式，正文字段不含段首标签（标签由静态页渲染）：牌在对你说话 / 心理层面 / 灵性层面 / 行动路径 / 大师总结。
 * 【判读锚定】与感情库一致：Rider–Waite–Smith 系为主；《塔罗葵花宝典》为中文实务主锚；逆位取通行读本（阻滞、内敛、过度等）。
 * 【逻辑】题干文案须与 `lib/tarot-question-quick-pick.ts` 中「事业工作」下列表完全一致（含标点）。
 * 【入库】`register(事业工作, 题干, dmy牌id, 正逆, content)`；未入库组合在静态页走通用事业大师解读，直至补 register。
 * 【禁止】工具箱类扩展（水晶颜色数字香氛等独立清单）；占位文案仅用于开发期调试（`placeholder: true`），正式条目不冒充。
 *
 * 【装配】`npm run build:tarot-question-career` → `public/tarotQuestionCareerContent.js`（全局 `TarotQuestionCareer`）。
 */

export interface MasterQuestionCardContent {
  cardSpeaking: string;
  psychologyLayer: string;
  spiritLayer: string;
  actionPath: string;
  masterSummary: string;
  isPlaceholder?: boolean;
}

const 事业工作 = '事业工作';

