const Q换行从头来过 = '我该不该换行从头来过？';

register(事业工作, Q换行从头来过, 'major_0', true, {
  cardSpeaking: `你工位上的灯还亮着，手里却握着另一行业的招聘链接。愚者把背包往肩上一甩：换行不是把过去烧了，是承认你不想再为旧剧本续集写台词。他问的不是「哪行更赚」，是你敢不敢让履历上出现一段「不连贯」的人生。`,
  psychologyLayer: `【职场现状】你卡在「熟悉的不甘心」与「陌生的不敢」之间：旧行你能交差，但兴奋感像过期文件；新行像未命名文件夹，你怕打开之后全是空白页。\n\n【心理层面】你反复算风险，其实是在拖延一次身份改写。你怕的不是学不会，是怕别人问「你以前不是干得好好的吗」——那句话像考勤机，打在你自尊上。\n\n【根源层面】你把连贯履历当成道德，把转弯当成失败。愚者提醒你：职业身份不是铁轨，是你可以自己改道的河。`,
  spiritLayer: `周期在转折处会格外吵：旧系统还在推送通知，新系统还没给你账号。宇宙让你看见：真正的「从头」往往不是清零，是允许自己从学徒重新开始一次。\n\n核心提醒：你若只换工牌不换心态，换行只是换一间牢房；若愿带着谦卑进新门，零基础也是礼物。`,
  actionPath: `本周做一次「不辞职的试水」：约两位目标行业在职者各聊 25 分钟，只问「他们最痛的日常」与「最硬的门槛」，不做幻想式调研。\n\n行囊检查：你舍不得扔的，是稳定感、面子，还是「我本该更成功」的怨气？写下一样本周可以松手的执念（哪怕只是少刷一小时对比帖）。`,
  masterSummary: `换行不是找更亮的舞台，是找你还愿意上台的那一出。`,
});

register(事业工作, Q换行从头来过, 'major_0', false, {
  cardSpeaking: `你把新行业的页面开了又关，像反复点开一封没写完的邮件。愚者逆位凑近看：你不是没冲动，是把冲动当成了计划——收藏夹越来越满，人还在旧会议室里点头。他说，你不是问该不该换，是问「我能不能不承担后果地换」。`,
  psychologyLayer: `【职场现状】表面在观望，内里在耗竭：你对旧活计失去敬意，又对新赛道只敢远观。身体在工位，注意力在招聘软件上漂。\n\n【心理层面】你怕一踏出去就「证明自己不行」，于是用「再准备一下」当护身符。你也怕身边人评价，于是把决定无限期押后。\n\n【根源层面】你曾经某次冒进摔过，或见过别人摔，于是把谨慎写成性格。逆位的愚者说：谨慎若变成自我扣押，就不再是智慧。`,
  spiritLayer: `能量在下沉时，会先变成烦躁与迟到、敷衍与抱怨。宇宙在提醒：你不是被困在行里，是被困在「不敢认领自己真正想要的生活」里。\n\n核心提醒：真正的危险不是换错行，是用十年停在「差一点就换」的原地。`,
  actionPath: `三天内完成一件极小但对外可见的动作：投出一份真实申请、发出一封求带教的短邮，或报名一门能写进简历片段的课——三选一，做完即止，不补完美条件。\n\n行囊检查：你是不是背着「别人的期待」在走路？写下一句只属于你自己的职业句子（以「我想要…」开头），贴在可见处。`,
  masterSummary: `你不是没路，是还没允许自己踩上第一条不体面的台阶。`,
});

